contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking all inputs that drive c.transfer
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // require the lengths match and non-empty to satisfy C.transfer's require
        require(_tos.length > 0 && _tos.length == v.length);

        // Perform the call and capture whether it reverted
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: C.transfer never returns false; it either reverts or returns true
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

