contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function with parameters mirroring C.transfer
    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        // require preconditions to exercise the function as intended
        require(_tos.length > 0 && _tos.length == v.length);

        bool didRevert;
        bool returnedTrue;

        // call under test: top-level state-changing call
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            didRevert = false;
            returnedTrue = r;
        } catch {
            didRevert = true;
            returnedTrue = false;
        }

        // General rule: it is impossible that the call both reverts and returns true; if it returned, it must be true
        assert(!(didRevert && returnedTrue) );
    }

    receive() external payable {}
}
